const {characters,guides}=window.ATLAS;
function read(k,f){try{return JSON.parse(localStorage.getItem(k))||f}catch{return f}}let saved=read('atlas-saved',[]),ranks=read('atlas-ranks',{});if(!Array.isArray(saved))saved=[];if(!ranks||typeof ranks!=='object')ranks={};const names=new Set(characters.map(c=>c.name));saved=saved.filter(n=>names.has(n));function persist(){try{localStorage.setItem('atlas-saved',JSON.stringify(saved));localStorage.setItem('atlas-ranks',JSON.stringify(ranks))}catch{toast('Browser storage unavailable. Changes last for this visit.')}}function toast(t){let e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');clearTimeout(window.tt);window.tt=setTimeout(()=>e.classList.remove('show'),2200)}
function syncSaves(){document.querySelectorAll('[data-save]').forEach(b=>{let yes=saved.includes(b.dataset.save);b.classList.toggle('saved',yes);b.setAttribute('aria-pressed',yes);b.setAttribute('aria-label',(yes?'Unsave ':'Save ')+b.dataset.save);b.textContent=b.classList.contains('save')?(yes?'♥':'♡'):(yes?'♥ Saved character':'♡ Save character')})}document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{let n=b.dataset.save;saved=saved.includes(n)?saved.filter(x=>x!==n):[...saved,n];persist();syncSaves();if(document.querySelector('#character-grid'))filterCharacters();toast(saved.includes(n)?n+' saved':n+' removed from saved')});syncSaves();
const directory=document.querySelector('#character-grid');let element=new URLSearchParams(location.search).get('element')||'all',onlySaved=false;function filterCharacters(){const q=document.querySelector('#character-search').value.trim().toLowerCase(),rarity=document.querySelector('#rarity-filter').value;let count=0;directory.querySelectorAll('.character-card').forEach(c=>{let name=c.querySelector('[data-save]').dataset.save;let yes=c.dataset.name.includes(q)&&(element==='all'||element===c.dataset.element)&&(rarity==='all'||rarity===c.dataset.rarity)&&(!onlySaved||saved.includes(name));c.hidden=!yes;if(yes)count++});document.querySelector('#result-count').textContent=count+' character'+(count===1?'':'s');document.querySelector('#empty-state').hidden=count!==0;document.querySelectorAll('[data-element-filter]').forEach(b=>{let on=b.dataset.elementFilter===element;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',on)});let url=new URL(location.href);element==='all'?url.searchParams.delete('element'):url.searchParams.set('element',element);history.replaceState(null,'',url.pathname+url.search)}if(directory){if(!['Ignis','Aqua','Ventus','Terra','Lux','Umbra'].includes(element))element='all';document.querySelector('#character-search').oninput=filterCharacters;document.querySelector('#rarity-filter').onchange=filterCharacters;document.querySelectorAll('[data-element-filter]').forEach(b=>b.onclick=()=>{element=b.dataset.elementFilter;filterCharacters()});document.querySelector('.saved-filter').onclick=e=>{onlySaved=!onlySaved;e.currentTarget.setAttribute('aria-pressed',onlySaved);e.currentTarget.classList.toggle('selected',onlySaved);filterCharacters()};document.querySelector('#clear-filters').onclick=()=>{element='all';onlySaved=false;document.querySelector('#character-search').value='';document.querySelector('#rarity-filter').value='all';document.querySelector('.saved-filter').setAttribute('aria-pressed',false);document.querySelector('.saved-filter').classList.remove('selected');filterCharacters()};filterCharacters()}
document.querySelectorAll('[data-guide-filter]').forEach(b=>b.onclick=()=>{let f=b.dataset.guideFilter;document.querySelectorAll('[data-guide-filter]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});document.querySelectorAll('.guide-tile').forEach(c=>c.hidden=f!=='All'&&c.dataset.category!==f)});
function renderBoard(){document.querySelector('#tier-board').innerHTML=['S','A','B','Unranked'].map(r=>{let cs=characters.filter(c=>(['S','A','B'].includes(ranks[c.name])?ranks[c.name]:'Unranked')===r);return `<div class="tier-row"><div class="tier-label">${r}</div><div class="tier-items">${cs.length?cs.map(c=>`<a class="tier-item" href="/characters/${c.slug}/" title="${c.name}"><img src="${c.portrait}" alt="${c.name}" loading="lazy"><span>${c.name}</span></a>`).join(''):'<span class="tier-empty">Choose characters from the roster →</span>'}</div></div>`}).join('')}
function renderRankPicker(){let q=document.querySelector('#rank-search').value.toLowerCase();let cs=characters.filter(c=>c.name.toLowerCase().includes(q));document.querySelector('#rank-list').innerHTML=cs.length?cs.map(c=>`<div class="rank-control"><img src="${c.portrait}" alt="" loading="lazy"><a href="/characters/${c.slug}/">${c.name}<small>${c.element} · ${c.rarity} stars</small></a><select aria-label="Rank ${c.name}" data-rank="${c.name}">${['Unranked','S','A','B'].map(r=>`<option ${r===(['S','A','B'].includes(ranks[c.name])?ranks[c.name]:'Unranked')?'selected':''}>${r}</option>`).join('')}</select></div>`).join(''):'<p>No characters found.</p>';document.querySelectorAll('[data-rank]').forEach(s=>s.onchange=()=>{ranks[s.dataset.rank]=s.value;persist();renderBoard();toast(s.dataset.rank+' → '+s.value)})}if(document.querySelector('#tier-board')){let slug=new URLSearchParams(location.search).get('character');let c=characters.find(c=>c.slug===slug);if(c)document.querySelector('#rank-search').value=c.name;renderBoard();renderRankPicker();document.querySelector('#rank-search').oninput=renderRankPicker;document.querySelector('#reset-tier').onclick=()=>{ranks={};persist();renderBoard();renderRankPicker();toast('All characters are now unranked')};}
const dialog=document.querySelector('#search-dialog'),input=document.querySelector('#global-search');function search(){let q=input.value.trim().toLowerCase();let all=[...characters.map(c=>({label:c.name,type:c.element+' · Character',url:'/characters/'+c.slug+'/',keywords:c.element})),...guides.map(g=>({label:g.title,type:'Guide',url:'/guides/'+g.slug+'/',keywords:g.category+' '+g.description}))];let rows=all.filter(x=>(x.label+' '+x.keywords).toLowerCase().includes(q));document.querySelector('#search-results').innerHTML=rows.length?rows.map(x=>`<a href="${x.url}">${x.label}<small>${x.type} ↗</small></a>`).join(''):'<p>No matches. Try a character name or topic.</p>'}document.querySelector('.search-open').onclick=()=>{dialog.showModal();search();input.focus()};input.oninput=search;document.querySelector('.close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){let r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!dialog.open){e.preventDefault();document.querySelector('.search-open').click()}});
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{threshold:.05});document.querySelectorAll('.section,.closing,.reading-content>section').forEach(e=>{e.classList.add('reveal');io.observe(e)});const sections=document.querySelectorAll('.reading-content>section[id]');if(sections.length){const toc=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)document.querySelectorAll('.toc a[href^="#"]').forEach(a=>a.classList.toggle('current',a.hash==='#'+e.target.id))}),{rootMargin:'-15% 0px -65% 0px'});sections.forEach(e=>toc.observe(e))}
