function svg(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${iconPaths[name]}</svg>`}
function decorateIcons(){document.querySelectorAll('[data-save]').forEach(b=>{let yes=b.getAttribute('aria-pressed')==='true';b.innerHTML=svg('heart')+(b.classList.contains('save')?'':` ${yes?'Saved character':'Save character'}`)});}
const oldSyncSaves=syncSaves;syncSaves=function(){oldSyncSaves();decorateIcons()};decorateIcons();
document.querySelectorAll('.brand-icon').forEach(el=>el.innerHTML=svg('star'));
